-- ---------------------------------------------------------------------------
-- EVGrid — MySQL 8 schema
-- ---------------------------------------------------------------------------
-- Derived directly from docs/BACKEND-ENDPOINTS.md section 6 (the frontend
-- contract) plus the extra columns the React pages actually read/write.
--
-- This file creates structure only. It contains NO INSERT statements: every
-- row in the database must be produced by the application.
--
-- Ids are CHAR(36) UUIDs generated by the API so that the frontend can treat
-- them as opaque strings (it calls `id.slice(...)` in a few places).
--
-- Apply with:  npm run db:setup      (or)  mysql -u root -p < backend/db/schema.sql
-- ---------------------------------------------------------------------------

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  id                     CHAR(36)      NOT NULL,
  email                  VARCHAR(191)  NOT NULL,
  password_hash          VARCHAR(255)  NULL,
  full_name              VARCHAR(191)  NULL,
  phone                  VARCHAR(32)   NULL,
  city                   VARCHAR(96)   NULL,
  favorite_connector     ENUM('Type 2','CCS2','CHAdeMO','Type 1','GB/T') NULL,
  notifications_enabled  TINYINT(1)    NOT NULL DEFAULT 1,
  auto_charge_reminders  TINYINT(1)    NOT NULL DEFAULT 1,
  app_role               ENUM('ev_user','operator','technician','admin') NOT NULL DEFAULT 'ev_user',
  role                   VARCHAR(32)   NOT NULL DEFAULT 'user',
  email_verified         TINYINT(1)    NOT NULL DEFAULT 0,
  otp_code               VARCHAR(255)  NULL,
  otp_expires_at         DATETIME      NULL,
  reset_token_hash       VARCHAR(255)  NULL,
  reset_expires_at       DATETIME      NULL,
  last_login_at          DATETIME      NULL,
  created_date           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email),
  KEY idx_users_app_role (app_role)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- operators
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS operators (
  id                  CHAR(36)      NOT NULL,
  org_name            VARCHAR(191)  NOT NULL,
  contact_name        VARCHAR(191)  NULL,
  email               VARCHAR(191)  NULL,
  phone               VARCHAR(32)   NULL,
  city                VARCHAR(96)   NULL,
  status              ENUM('active','pending','suspended') NOT NULL DEFAULT 'pending',
  commission_percent  DECIMAL(5,2)  NOT NULL DEFAULT 8.00,
  stations_count      INT           NOT NULL DEFAULT 0,
  onboarded_date      DATE          NULL,
  created_date        DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_operators_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- charging_stations
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS charging_stations (
  id               CHAR(36)      NOT NULL,
  name             VARCHAR(191)  NOT NULL,
  city             VARCHAR(96)   NOT NULL,
  state            VARCHAR(96)   NULL,
  address          VARCHAR(255)  NULL,
  status           ENUM('online','maintenance','offline') NOT NULL DEFAULT 'online',
  connector_types  JSON          NULL,
  max_power_kw     DECIMAL(8,2)  NOT NULL DEFAULT 0,
  price_per_kwh    DECIMAL(8,2)  NOT NULL DEFAULT 0,
  operator_name    VARCHAR(191)  NULL,
  open_24h         TINYINT(1)    NOT NULL DEFAULT 1,
  opening_hours    VARCHAR(96)   NULL,
  amenities        JSON          NULL,
  description      TEXT          NULL,
  image_url        VARCHAR(512)  NULL,
  rating           DECIMAL(3,2)  NOT NULL DEFAULT 0,
  review_count     INT           NOT NULL DEFAULT 0,
  total_points     INT           NOT NULL DEFAULT 0,
  latitude         DECIMAL(10,7) NULL,
  longitude        DECIMAL(10,7) NULL,
  created_date     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_stations_city (city),
  KEY idx_stations_status (status),
  KEY idx_stations_rating (rating)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- charging_points
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS charging_points (
  id                  CHAR(36)     NOT NULL,
  station_id          CHAR(36)     NOT NULL,
  code                VARCHAR(32)  NOT NULL,
  connector_type      VARCHAR(32)  NOT NULL DEFAULT 'CCS2',
  current_type        ENUM('AC','DC') NOT NULL DEFAULT 'DC',
  power_kw            DECIMAL(8,2) NOT NULL DEFAULT 0,
  status              ENUM('available','occupied','reserved','offline','maintenance') NOT NULL DEFAULT 'available',
  serial_number       VARCHAR(96)  NULL,
  last_serviced_date  DATE         NULL,
  created_date        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_points_station_code (station_id, code),
  KEY idx_points_status (status),
  CONSTRAINT fk_points_station FOREIGN KEY (station_id)
    REFERENCES charging_stations (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- vehicles
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS vehicles (
  id                    CHAR(36)     NOT NULL,
  user_id               CHAR(36)     NOT NULL,
  nickname              VARCHAR(96)  NULL,
  make                  VARCHAR(96)  NOT NULL,
  model                 VARCHAR(96)  NOT NULL,
  year                  INT          NULL,
  registration_number   VARCHAR(32)  NOT NULL,
  battery_capacity_kwh  DECIMAL(8,2) NULL,
  range_km              INT          NULL,
  connector_type        VARCHAR(32)  NULL,
  is_primary            TINYINT(1)   NOT NULL DEFAULT 0,
  created_date          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_vehicles_registration (registration_number),
  KEY idx_vehicles_user (user_id),
  CONSTRAINT fk_vehicles_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- bookings
--   `user_id` is the owning EV driver; the API also returns it as
--   `created_by_id` because the Bookings page reads that key.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS bookings (
  id                     CHAR(36)      NOT NULL,
  user_id                CHAR(36)      NOT NULL,
  user_name              VARCHAR(191)  NULL,
  station_id             CHAR(36)      NOT NULL,
  station_name           VARCHAR(191)  NULL,
  point_id               CHAR(36)      NOT NULL,
  point_code             VARCHAR(32)   NULL,
  vehicle_id             CHAR(36)      NULL,
  vehicle_label          VARCHAR(191)  NULL,
  booking_date           DATE          NOT NULL,
  start_time             TIME          NOT NULL,
  end_time               TIME          NOT NULL,
  duration_minutes       INT           NULL,
  estimated_energy_kwh   DECIMAL(10,2) NULL,
  estimated_cost         DECIMAL(10,2) NULL,
  status                 ENUM('pending','confirmed','active','completed','cancelled','no_show') NOT NULL DEFAULT 'confirmed',
  notes                  TEXT          NULL,
  created_date           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_bookings_user (user_id),
  KEY idx_bookings_slot (point_id, booking_date, start_time),
  KEY idx_bookings_status (status),
  CONSTRAINT fk_bookings_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_bookings_station FOREIGN KEY (station_id)
    REFERENCES charging_stations (id) ON DELETE RESTRICT,
  CONSTRAINT fk_bookings_point FOREIGN KEY (point_id)
    REFERENCES charging_points (id) ON DELETE RESTRICT,
  CONSTRAINT fk_bookings_vehicle FOREIGN KEY (vehicle_id)
    REFERENCES vehicles (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- charging_sessions
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS charging_sessions (
  id                CHAR(36)      NOT NULL,
  booking_id        CHAR(36)      NULL,
  user_id           CHAR(36)      NOT NULL,
  station_id        CHAR(36)      NULL,
  station_name      VARCHAR(191)  NULL,
  point_id          CHAR(36)      NULL,
  point_code        VARCHAR(32)   NULL,
  vehicle_id        CHAR(36)      NULL,
  vehicle_label     VARCHAR(191)  NULL,
  start_time        DATETIME      NOT NULL,
  end_time          DATETIME      NULL,
  duration_minutes  INT           NULL,
  energy_kwh        DECIMAL(10,2) NULL,
  cost              DECIMAL(10,2) NULL,
  status            ENUM('in_progress','completed','aborted') NOT NULL DEFAULT 'in_progress',
  created_date      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_sessions_user (user_id),
  KEY idx_sessions_status (status),
  KEY idx_sessions_start (start_time),
  CONSTRAINT fk_sessions_booking FOREIGN KEY (booking_id)
    REFERENCES bookings (id) ON DELETE SET NULL,
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_sessions_station FOREIGN KEY (station_id)
    REFERENCES charging_stations (id) ON DELETE SET NULL,
  CONSTRAINT fk_sessions_point FOREIGN KEY (point_id)
    REFERENCES charging_points (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- payments
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS payments (
  id              CHAR(36)      NOT NULL,
  session_id      CHAR(36)      NULL,
  booking_id      CHAR(36)      NULL,
  user_id         CHAR(36)      NOT NULL,
  station_id      CHAR(36)      NULL,
  station_name    VARCHAR(191)  NULL,
  invoice_number  VARCHAR(64)   NULL,
  amount          DECIMAL(10,2) NOT NULL DEFAULT 0,
  energy_kwh      DECIMAL(10,2) NULL,
  method          ENUM('upi','card','wallet','netbanking','cash') NULL,
  status          ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending',
  transaction_ref VARCHAR(96)   NULL,
  paid_date       DATETIME      NULL,
  created_date    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_payments_invoice (invoice_number),
  KEY idx_payments_user (user_id),
  KEY idx_payments_status (status),
  CONSTRAINT fk_payments_session FOREIGN KEY (session_id)
    REFERENCES charging_sessions (id) ON DELETE SET NULL,
  CONSTRAINT fk_payments_booking FOREIGN KEY (booking_id)
    REFERENCES bookings (id) ON DELETE SET NULL,
  CONSTRAINT fk_payments_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_payments_station FOREIGN KEY (station_id)
    REFERENCES charging_stations (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- notifications
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS notifications (
  id            CHAR(36)      NOT NULL,
  user_id       CHAR(36)      NOT NULL,
  title         VARCHAR(191)  NOT NULL,
  message       TEXT          NULL,
  type          ENUM('booking','payment','session','maintenance','system') NOT NULL DEFAULT 'system',
  link          VARCHAR(255)  NULL,
  is_read       TINYINT(1)    NOT NULL DEFAULT 0,
  created_date  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_notifications_user_read (user_id, is_read),
  CONSTRAINT fk_notifications_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- maintenance_records
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS maintenance_records (
  id                CHAR(36)     NOT NULL,
  station_id        CHAR(36)     NULL,
  station_name      VARCHAR(191) NULL,
  point_id          CHAR(36)     NULL,
  point_code        VARCHAR(32)  NULL,
  title             VARCHAR(191) NOT NULL,
  description       TEXT         NULL,
  category          ENUM('hardware','software','cable','connector','network','other') NOT NULL DEFAULT 'hardware',
  priority          ENUM('low','medium','high','critical') NOT NULL DEFAULT 'medium',
  status            ENUM('open','assigned','in_progress','resolved') NOT NULL DEFAULT 'open',
  assigned_to       VARCHAR(191) NULL,
  assigned_email    VARCHAR(191) NULL,
  reported_by_name  VARCHAR(191) NULL,
  reported_date     DATE         NULL,
  resolved_date     DATE         NULL,
  resolution_notes  TEXT         NULL,
  created_date      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_maintenance_status (status),
  KEY idx_maintenance_station (station_id),
  KEY idx_maintenance_assigned (assigned_email),
  CONSTRAINT fk_maintenance_station FOREIGN KEY (station_id)
    REFERENCES charging_stations (id) ON DELETE CASCADE,
  CONSTRAINT fk_maintenance_point FOREIGN KEY (point_id)
    REFERENCES charging_points (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- technicians
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS technicians (
  id              CHAR(36)     NOT NULL,
  name            VARCHAR(191) NOT NULL,
  email           VARCHAR(191) NOT NULL,
  phone           VARCHAR(32)  NULL,
  city            VARCHAR(96)  NULL,
  specialization  VARCHAR(191) NULL,
  is_active       TINYINT(1)   NOT NULL DEFAULT 1,
  created_date    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_technicians_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- tariffs
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tariffs (
  id                CHAR(36)     NOT NULL,
  station_id        CHAR(36)     NULL,
  station_name      VARCHAR(191) NULL,
  name              VARCHAR(96)  NOT NULL,
  price_per_kwh     DECIMAL(8,2) NOT NULL DEFAULT 0,
  session_fee       DECIMAL(8,2) NOT NULL DEFAULT 0,
  idle_fee_per_min  DECIMAL(8,2) NOT NULL DEFAULT 0,
  currency          VARCHAR(8)   NOT NULL DEFAULT 'INR',
  is_active         TINYINT(1)   NOT NULL DEFAULT 1,
  valid_from        DATE         NULL,
  created_date      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_tariffs_station (station_id),
  CONSTRAINT fk_tariffs_station FOREIGN KEY (station_id)
    REFERENCES charging_stations (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- reviews
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS reviews (
  id            CHAR(36)     NOT NULL,
  station_id    CHAR(36)     NULL,
  station_name  VARCHAR(191) NULL,
  user_id       CHAR(36)     NULL,
  user_name     VARCHAR(191) NULL,
  rating        TINYINT      NOT NULL DEFAULT 5,
  comment       TEXT         NULL,
  created_date  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_reviews_station (station_id),
  CONSTRAINT fk_reviews_station FOREIGN KEY (station_id)
    REFERENCES charging_stations (id) ON DELETE CASCADE,
  CONSTRAINT fk_reviews_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- favorites
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS favorites (
  id            CHAR(36)     NOT NULL,
  user_id       CHAR(36)     NOT NULL,
  station_id    CHAR(36)     NOT NULL,
  station_name  VARCHAR(191) NULL,
  city          VARCHAR(96)  NULL,
  created_date  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_favorites_user_station (user_id, station_id),
  CONSTRAINT fk_favorites_user FOREIGN KEY (user_id)
    REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_favorites_station FOREIGN KEY (station_id)
    REFERENCES charging_stations (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- audit_logs
--   `details` holds a human-readable summary string (a JSON scalar) because
--   the Audit log and Admin dashboard render it directly inside a template.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit_logs (
  id            CHAR(36)      NOT NULL,
  action        VARCHAR(96)   NOT NULL,
  entity_type   VARCHAR(64)   NULL,
  entity_id     VARCHAR(64)   NULL,
  actor_id      CHAR(36)      NULL,
  actor_name    VARCHAR(191)  NULL,
  actor_email   VARCHAR(191)  NULL,
  details       JSON          NULL,
  severity      ENUM('info','warning','critical') NOT NULL DEFAULT 'info',
  ip_address    VARCHAR(64)   NULL,
  created_date  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_audit_created (created_date),
  KEY idx_audit_severity (severity),
  CONSTRAINT fk_audit_actor FOREIGN KEY (actor_id)
    REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
